/** Shown on the home page. Order here is display order. */
const POPULAR = [
  "dhaka",
  "uttara",
  "bashundhara",
  "mirpur",
  "dhanmondi",
  "mohammadpur",
  "gulshan",
  "banani",
  "chattogram",
  "sylhet",
];

function build(): LocationSeed[] {
  const all: LocationSeed[] = [];
  let order = 100;

  const add = (row: Row, type: LocationType, slug: string, parent: string | null) => {
    const [, nameBn, nameEn, latitude, longitude, altNames = []] = row;
    order += 10;
    all.push({
      slug,
      type,
      parent,
      nameBn,
      nameEn,
      altNames,
      latitude,
      longitude,
      isPopular: type !== "division" && type !== "district" && POPULAR.includes(slug),
      sortOrder: order,
    });
  };

  for (const division of DIVISIONS) {
    const divisionSlug = `${division[0]}-division`;
    add(division, "division", divisionSlug, null);

    for (const district of DISTRICTS[division[0]] ?? []) {
      const districtSlug = `${district[0]}-district`;
      add(district, "district", districtSlug, divisionSlug);

      const city = CITIES[district[0]];
      if (city) {
        add(city, "city", city[0], districtSlug);
        for (const area of AREAS[city[0]] ?? []) add(area, "area", area[0], city[0]);
      }
      for (const upazila of UPAZILAS[district[0]] ?? []) add(upazila, "upazila", upazila[0], districtSlug);
    }
  }

  // Popular places sort by their position in POPULAR, ahead of everything else.
  for (const location of all) {
    const rank = POPULAR.indexOf(location.slug);
    if (location.isPopular && rank >= 0) location.sortOrder = rank + 1;
  }

  return all;
}

export const LOCATIONS: LocationSeed[] = build();
